function Reports({data,month,fmt,exportJson,exportCsv,setModal}:{data:State;month:string;fmt:(n:number)=>string;exportJson:()=>void;exportCsv:()=>void;setModal:(m:Modal)=>void}){const years=Array.from({length:4},(_,i)=>Number(month.slice(0,4))-3+i).map(year=>{let income=0,expense=0;for(let m=1;m<=12;m++){const t=summary(data,`${year}-${String(m).padStart(2,'0')}`);income+=t.income;expense+=t.expense;}return {year,income,expense};});return <div className="space-y-6"><section className="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div className="border-b border-slate-100 p-5"><h2 className="font-semibold">Resumo anual</h2></div><div className="overflow-x-auto"><table className="w-full min-w-[600px] text-left text-sm"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-4">Ano</th><th>Ganhos</th><th>Despesas</th><th>Saldo</th></tr></thead><tbody>{years.map(y=><tr className="border-t border-slate-100" key={y.year}><td className="p-4 font-semibold">{y.year}</td><td className="text-emerald-600">{fmt(y.income)}</td><td>{fmt(y.expense)}</td><td className={y.income-y.expense>=0?'text-indigo-600':'text-red-600'}>{fmt(y.income-y.expense)}</td></tr>)}</tbody></table></div></section><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-5"><ActionCard icon={<Upload/>} title="Importar extrato" text="Leia arquivos OFX ou CSV do banco." action={()=>setModal('import')}/><ActionCard icon={<Tag/>} title="Nova categoria" text="Personalize a organização dos gastos." action={()=>setModal('category')}/><ActionCard icon={<FileDown/>} title="Exportar CSV" text="Abra os lançamentos em planilhas." action={exportCsv}/><ActionCard icon={<ShieldCheck/>} title="Backup completo" text="Baixe uma cópia JSON de todos os registros." action={exportJson}/><ActionCard icon={<SlidersHorizontal/>} title="Conta e privacidade" text="Veja a sessão ou exclua sua conta." action={()=>setModal('account')}/></div></div>}
